// 01 - Controller & PHY: the GENET v5 MAC and the BCM54213PE PHY.
// One suite, one file: it registers itself with the runner; there is no
// list of suites to keep in step with the files.
// GENERATED by micro-os-scaffold (--micro-test-plus).
#include <mtp_board.hpp>
#include "eth_helpers.hpp"

using namespace os::rtos;
using namespace mtp_eth;

mt::static_suite suite_controller{
  "01 - Controller & PHY", mtp_board::runner (),
  [] (mt::suite& ts) {
    ts.test ("GENET v5 MAC and BCM54213PE RGMII PHY respond", [] (auto& t) {
      g_up = app::bring_up (ETH_TEST_STATIC_IP, ETH_TEST_GATEWAY);
      const unsigned ver = genet::version ();
      const std::uint32_t phy = genet::phy_id ();
      std::printf ("# GENET v%u, PHY ID 0x%08x\n", ver,
                   static_cast<unsigned> (phy));
      t.expect (g_up.controller) << "genet::start () succeeded";
      t.expect (mt::eq (ver, 5u))
          << "Broadcom GENET major version 5 (SYS_REV_CTRL)";
      t.expect (mt::all_of (mt::ne (phy, 0u), mt::ne (phy, 0xffffffffu)))
          << fmt ("BCM54213PE MDIO PHY ID 0x%08x", static_cast<unsigned> (phy));
    });

    ts.test ("station MAC address is a valid unicast address", [] (auto& t) {
      const auto& mac = genet::address ();
      const char* src = genet::address_source ();
      std::printf ("# MAC %02x:%02x:%02x:%02x:%02x:%02x (%s)\n", mac[0], mac[1],
                   mac[2], mac[3], mac[4], mac[5], src);
      const bool non_zero
          = (mac[0] | mac[1] | mac[2] | mac[3] | mac[4] | mac[5]) != 0;
      const bool unicast = (mac[0] & 0x01u) == 0;
      t.expect (non_zero) << "station MAC address is non-zero";
      t.expect (unicast) << "MAC I/G bit is 0 (unicast)";
      t.expect (src != nullptr && src[0] != '\0')
          << fmt_str ("MAC address source: %s", src);
    });
  }
};
